    map['price'] = Variable<int>(price);
    if (!nullToAbsent || manualCost != null) {
      map['manual_cost'] = Variable<int>(manualCost);
    }
    map['active'] = Variable<bool>(active);
    map['sort_order'] = Variable<int>(sortOrder);
    return map;
  }

