class SaleLineRow extends DataClass implements Insertable<SaleLineRow> {
  final String id;
  final DateTime createdAt;
  final DateTime updatedAt;
  final DateTime? deletedAt;

  /// When the server last confirmed this row. Null means not yet synced.
  final DateTime? syncedAt;
  final String deviceId;
  final String saleId;
  final String productId;
  final String? variantId;

  /// Names as sold, so the sale reads the same after the menu changes.
  final String productName;
  final String? variantName;
  final int quantity;

  /// Pesewas for one unit, add-ons included.
  final int unitPrice;

  /// Pesewas.
  final int lineTotal;

  /// The options picked, as sold (JSON). Named addons for history.
  final List<SoldAddon> addons;

  /// Pesewas: what the stock used cost (recipes), for profit. v5.
  final int costTotal;

  /// Pesewas of tax in (or on top of) the line. v5.
  final int taxTotal;

  /// Counted, or weighed (then [quantity] is grams or ml and [unitPrice] is
  /// per kg or litre). v6.
  final SellBy sellBy;

  /// The menu price for one, when the price was overridden or typed in. v6.
  final int? listPrice;

  /// Who overrode the price (the person whose permission was used). v6.
  final String? priceOverriddenBy;

  /// Pesewas off this line, and its share of the order discount. [lineTotal]
  /// is before both. v6.
  final int discount;
  final int orderDiscountShare;

  /// The line discount as given (JSON: kind, value, reason, name). v6.
  final String? discountDetail;
  final String? note;

  /// Stock this line used, {stockItemId: base units} (JSON), so a refund
  /// puts back exactly that. Null before v7.
  final String? stockUsed;
  const SaleLineRow({
    required this.id,
    required this.createdAt,
    required this.updatedAt,
    this.deletedAt,
    this.syncedAt,
    required this.deviceId,
    required this.saleId,
    required this.productId,
    this.variantId,
    required this.productName,
    this.variantName,
    required this.quantity,
    required this.unitPrice,
    required this.lineTotal,
    required this.addons,
    required this.costTotal,
    required this.taxTotal,
    required this.sellBy,
    this.listPrice,
    this.priceOverriddenBy,
    required this.discount,
    required this.orderDiscountShare,
    this.discountDetail,
    this.note,
    this.stockUsed,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<String>(id);
    map['created_at'] = Variable<DateTime>(createdAt);
    map['updated_at'] = Variable<DateTime>(updatedAt);
    if (!nullToAbsent || deletedAt != null) {
      map['deleted_at'] = Variable<DateTime>(deletedAt);
    }
    if (!nullToAbsent || syncedAt != null) {
      map['synced_at'] = Variable<DateTime>(syncedAt);
    }
    map['device_id'] = Variable<String>(deviceId);
    map['sale_id'] = Variable<String>(saleId);
    map['product_id'] = Variable<String>(productId);
    if (!nullToAbsent || variantId != null) {
      map['variant_id'] = Variable<String>(variantId);
    }
    map['product_name'] = Variable<String>(productName);
    if (!nullToAbsent || variantName != null) {
      map['variant_name'] = Variable<String>(variantName);
    }
    map['quantity'] = Variable<int>(quantity);
    map['unit_price'] = Variable<int>(unitPrice);
    map['line_total'] = Variable<int>(lineTotal);
    {
      map['addons'] = Variable<String>(
        $SaleLinesTable.$converteraddons.toSql(addons),
      );
    }
    map['cost_total'] = Variable<int>(costTotal);
    map['tax_total'] = Variable<int>(taxTotal);
    {
      map['sell_by'] = Variable<String>(
        $SaleLinesTable.$convertersellBy.toSql(sellBy),
      );
    }
    if (!nullToAbsent || listPrice != null) {
      map['list_price'] = Variable<int>(listPrice);
    }
    if (!nullToAbsent || priceOverriddenBy != null) {
      map['price_overridden_by'] = Variable<String>(priceOverriddenBy);
    }
    map['discount'] = Variable<int>(discount);
    map['order_discount_share'] = Variable<int>(orderDiscountShare);
    if (!nullToAbsent || discountDetail != null) {
      map['discount_detail'] = Variable<String>(discountDetail);
    }
    if (!nullToAbsent || note != null) {
      map['note'] = Variable<String>(note);
    }
    if (!nullToAbsent || stockUsed != null) {
      map['stock_used'] = Variable<String>(stockUsed);
    }
    return map;
  }

  SaleLinesCompanion toCompanion(bool nullToAbsent) {
    return SaleLinesCompanion(
      id: Value(id),
      createdAt: Value(createdAt),
      updatedAt: Value(updatedAt),
      deletedAt: deletedAt == null && nullToAbsent
          ? const Value.absent()
          : Value(deletedAt),
      syncedAt: syncedAt == null && nullToAbsent
          ? const Value.absent()
          : Value(syncedAt),
      deviceId: Value(deviceId),
      saleId: Value(saleId),
      productId: Value(productId),
      variantId: variantId == null && nullToAbsent
          ? const Value.absent()
          : Value(variantId),
      productName: Value(productName),
      variantName: variantName == null && nullToAbsent
          ? const Value.absent()
          : Value(variantName),
      quantity: Value(quantity),
      unitPrice: Value(unitPrice),
      lineTotal: Value(lineTotal),
      addons: Value(addons),
      costTotal: Value(costTotal),
      taxTotal: Value(taxTotal),
      sellBy: Value(sellBy),
      listPrice: listPrice == null && nullToAbsent
          ? const Value.absent()
          : Value(listPrice),
      priceOverriddenBy: priceOverriddenBy == null && nullToAbsent
          ? const Value.absent()
          : Value(priceOverriddenBy),
      discount: Value(discount),
      orderDiscountShare: Value(orderDiscountShare),
      discountDetail: discountDetail == null && nullToAbsent
          ? const Value.absent()
          : Value(discountDetail),
      note: note == null && nullToAbsent ? const Value.absent() : Value(note),
      stockUsed: stockUsed == null && nullToAbsent
          ? const Value.absent()
          : Value(stockUsed),
    );
  }

  factory SaleLineRow.fromJson(
    Map<String, dynamic> json, {
    ValueSerializer? serializer,
  }) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return SaleLineRow(
      id: serializer.fromJson<String>(json['id']),
      createdAt: serializer.fromJson<DateTime>(json['createdAt']),
      updatedAt: serializer.fromJson<DateTime>(json['updatedAt']),
      deletedAt: serializer.fromJson<DateTime?>(json['deletedAt']),
      syncedAt: serializer.fromJson<DateTime?>(json['syncedAt']),
      deviceId: serializer.fromJson<String>(json['deviceId']),
      saleId: serializer.fromJson<String>(json['saleId']),
      productId: serializer.fromJson<String>(json['productId']),
      variantId: serializer.fromJson<String?>(json['variantId']),
      productName: serializer.fromJson<String>(json['productName']),
      variantName: serializer.fromJson<String?>(json['variantName']),
      quantity: serializer.fromJson<int>(json['quantity']),
      unitPrice: serializer.fromJson<int>(json['unitPrice']),
      lineTotal: serializer.fromJson<int>(json['lineTotal']),
      addons: $SaleLinesTable.$converteraddons.fromJson(
        serializer.fromJson<List<dynamic>>(json['addons']),
      ),
