class StaffRow extends DataClass implements Insertable<StaffRow> {
  final String id;
  final DateTime createdAt;
  final DateTime updatedAt;
  final DateTime? deletedAt;

  /// When the server last confirmed this row. Null means not yet synced.
  final DateTime? syncedAt;
  final String deviceId;
  final String name;
  final String roleId;

  /// See PinHasher for the format.
  final String pinHash;
  final bool active;
  final String? phone;
  final String? email;

  /// Where they live, as people give directions ("behind the Lamashegu mosque").
  final String? address;
  final String? emergencyName;
  final String? emergencyPhone;

  /// Ghana Card number, e.g. GHA-123456789-0.
  final String? idNumber;
  final DateTime? dateOfBirth;
  final DateTime? startedOn;
  final String? notes;
  const StaffRow({
    required this.id,
    required this.createdAt,
    required this.updatedAt,
    this.deletedAt,
    this.syncedAt,
    required this.deviceId,
    required this.name,
    required this.roleId,
    required this.pinHash,
    required this.active,
    this.phone,
    this.email,
    this.address,
    this.emergencyName,
    this.emergencyPhone,
    this.idNumber,
    this.dateOfBirth,
    this.startedOn,
    this.notes,
  });
