class DayCloseRow extends DataClass implements Insertable<DayCloseRow> {
  final String id;
  final DateTime createdAt;
  final DateTime updatedAt;
  final DateTime? deletedAt;

  /// When the server last confirmed this row. Null means not yet synced.
  final DateTime? syncedAt;
  final String deviceId;

  /// The previous close's [closedAt]; null for the first close.
  final DateTime? periodStart;
  final DateTime closedAt;

  /// The highest sale number (this device) the close covers. The next period
  /// starts after it. Exact where timestamps (whole seconds) are not.
  final int lastSaleNumber;
  final String closedById;
  final String closedByName;
  final int salesCount;
  final int voidedCount;
  final int salesTotal;
  final int cashTakings;
  final int momoTakings;
  final int creditTakings;
  final int openingFloat;
  final int expectedCash;
  final int countedCash;
  final String? note;

  /// The highest refund number (this device) the close covers. v7.
  final int lastRefundNumber;
  final int refundsTotal;

  /// Cash paid out for refunds; [expectedCash] takes it off. v7.
  final int cashRefunds;

  /// Takings by card, bank and the other methods. v7.
  final int otherTakings;
  final int roundingTotal;
  final int noSaleCount;

  /// Cash from customers that was not a sale: repayments, wallet top-ups,
  /// change kept. [expectedCash] includes it. v8.
  final int customerCash;
  const DayCloseRow({
    required this.id,
    required this.createdAt,
    required this.updatedAt,
    this.deletedAt,
    this.syncedAt,
    required this.deviceId,
    this.periodStart,
    required this.closedAt,
    required this.lastSaleNumber,
    required this.closedById,
    required this.closedByName,
    required this.salesCount,
    required this.voidedCount,
    required this.salesTotal,
    required this.cashTakings,
    required this.momoTakings,
    required this.creditTakings,
    required this.openingFloat,
    required this.expectedCash,
    required this.countedCash,
    this.note,
    required this.lastRefundNumber,
    required this.refundsTotal,
    required this.cashRefunds,
    required this.otherTakings,
    required this.roundingTotal,
    required this.noSaleCount,
    required this.customerCash,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
